def count_nodes_at_same_level(tree):
    # Initialize a queue for BFS
    queue = [(0, 0)]  # (node_index, level)
    levels = {}

    while queue:
        node_index, level = queue.pop(0)

        if level not in levels:
            levels[level] = []

        levels[level].append(node_index)

        # Add children to the queue
        for child in tree[node_index]:
            queue.append((child, level + 1))

    result = [len(levels[level]) for level in sorted(levels.keys())]
    return result

