    nums.sort()  # Sort the array to make it easier to use two pointers

    for i in range(len(nums) - 2):  # Iterate through the array up to the third last element
        if i > 0 and nums[i] == nums[i-1]:  # Skip duplicates
            continue

        left, right = i + 1, len(nums) - 1  # Initialize two pointers

        while left < right:
            total = nums[i] + nums[left] + nums[right]

            if total == 0:
                res.append([nums[i], nums[left], nums[right]])

                # Move both pointers towards the center
                while left < right and nums[left] == nums[left+1]:
                    left += 1
                while left < right and nums[right] == nums[right-1]:
                    right -= 1

                left += 1
                right -= 1

            elif total < 0:
                left += 1  # Increase the sum by moving the left pointer to the right
            else:
